// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    X_WALLET c;
    Log log_;

    function setUp() public {
        log_ = new Log();
        c = new X_WALLET(address(log_));
    }

    function _countEntries() internal view returns (uint256 n) {
        n = 0;
        bool more = true;
        while (more && n < 100000) {
            try log_.History(n) returns (address, string memory, uint256, uint256) {
                n++;
            } catch {
                more = false;
            }
        }
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 100 ether);

        uint256 before_ = _countEntries();

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);

        uint256 after_ = _countEntries();
        (address sender, , uint256 val, ) = log_.History(after_ - 1);

        assertTrue(
            after_ == before_ + 1 && sender == actor && val == amount,
            "Put must append a log entry recording (sender, amount)"
        );
    }
}
